(()=>{const key=s=>String(s??'').replace(' | Waving','').replace(/\s+/g,' ').trim().replace(/\.$/,'').toLowerCase();const tr=s=>{if(s===undefined||s===null)return '';const raw=String(s),k=key(raw);if(/^Please complete /.test(raw))return 'Veuillez remplir le champ : '+raw.slice(16);if(/^Please check /.test(raw))return 'Veuillez vérifier le champ : '+raw.slice(13);let v=window.WAVING_FR[k];if(!v)return raw;if(raw.trim()===raw.trim().toUpperCase()&&/[a-z]/i.test(raw))v=v.toUpperCase();else if(v===v.toUpperCase()&&v.length>4)v=v.charAt(0)+v.slice(1).toLowerCase();if(raw.trim().endsWith('.')&&!v.endsWith('.'))v+='.';return raw.match(/^\s*/)[0]+v+raw.match(/\s*$/)[0]};window.wavingTranslate=tr;window.wavingLocalize=root=>{const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while(n=w.nextNode()){if(n.parentElement.closest('textarea,option,[data-i18n-skip]'))continue;n.textContent=tr(n.textContent)}root.querySelectorAll('a[href^="/"]').forEach(a=>{if(!a.getAttribute('href').startsWith('/fr/'))a.setAttribute('href','/fr'+a.getAttribute('href'))})}})();
